(()=>{
 const $=s=>document.querySelector(s),reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const journey=$('.journey'),stage=$('.stage'),world=$('.world'),header=$('.site-header'),surface=$('.surface-scene>img'),banks=[...document.querySelectorAll('.rock-bank')],cow=$('.cow-layer'),column=$('.front-column'),gallery=$('.shaft-gallery'),intro=$('.intro-words'),introBottom=$('.intro-bottom'),rail=$('.journey-nav'),links=[...rail.querySelectorAll('a')],progress=$('.page-progress i'),motion=$('.motion-toggle'),menu=$('.menu-toggle');
 let paused=reduced.matches,raf=0,last=0,visual=scrollY,height=innerHeight,start=0,pageRange=1,journeyRange=1,stops=[],active=-1;
 const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v)),top=el=>el.getBoundingClientRect().top+scrollY;
 function measure(){height=stage.clientHeight||innerHeight;start=top(journey);journeyRange=journey.clientHeight-height;pageRange=Math.max(1,document.documentElement.scrollHeight-innerHeight);const centered=el=>Math.max(0,top(el)-start+el.offsetHeight/2-height/2);stops=[{x:0,y:0},{x:centered($('.passage-words')),y:height*.96},{x:centered($('.temple-words')),y:height*2},{x:Math.max(journeyRange,centered($('.temple-words'))+1),y:height*2}];visual=scrollY;render(visual);}
 function cameraAt(x){const n=stops.length;if(x<=0)return 0;if(x>=stops[n-1].x)return stops[n-1].y;const slopes=stops.slice(1).map((s,i)=>(s.y-stops[i].y)/Math.max(1,s.x-stops[i].x));const tangent=i=>i===0?slopes[0]:i===n-1?0:slopes[i-1]*slopes[i]<=0?0:2*slopes[i-1]*slopes[i]/(slopes[i-1]+slopes[i]);for(let i=1;i<n;i++)if(x<=stops[i].x){const a=stops[i-1],b=stops[i],d=b.x-a.x,t=clamp((x-a.x)/d),t2=t*t,t3=t2*t;return (2*t3-3*t2+1)*a.y+(t3-2*t2+t)*d*tangent(i-1)+(-2*t3+3*t2)*b.y+(t3-t2)*d*tangent(i);}}
 function render(y){if(!stops.length)return;const local=Math.max(0,y-start),actual=scrollY-start,cam=cameraAt(local),move=paused||reduced.matches?0:1;world.style.transform=`translate3d(0,${-cam}px,0)`;
 surface.style.transform=`translate3d(0,${Math.min(height,cam)*.055*move}px,0)`;
 banks.forEach((bank,i)=>bank.style.transform=`translate3d(${(i?1:-1)*Math.min(cam/height,1.2)*25*move}px,${-Math.min(cam,height*1.5)*.11*move}px,0)`);
 gallery.style.transform=`translate3d(0,${-Math.min(cam,height*1.8)*.018*move}px,0)`;
 const temple=clamp((cam-height*1.35)/(height*.85));cow.style.transform=`translate3d(${(1-temple)*30*move}px,${(1-temple)*80*move}px,0)`;column.style.transform=`translate3d(${(1-temple)*65*move}px,${(1-temple)*45*move}px,0)`;
 intro.style.opacity=String(1-clamp(actual/(height*.55)));intro.style.transform=`translate3d(0,${-clamp(actual/height)*height*.04*move}px,0)`;intro.inert=actual>height*.65;introBottom.style.opacity=String(1-clamp(actual/(height*.28)));introBottom.inert=actual>height*.5;
 header.classList.toggle('is-deep',actual>height*.5);progress.style.transform=`scaleX(${clamp(scrollY/pageRange)})`;const chapter=local<stops[1].x*.6?0:local<(stops[1].x+stops[2].x)*.5?1:2;if(chapter!==active){active=chapter;links.forEach((a,i)=>{if(i===chapter)a.setAttribute('aria-current','step');else a.removeAttribute('aria-current');});}const hide=actual>journeyRange+height*.2;rail.classList.toggle('is-hidden',hide);rail.inert=hide;rail.setAttribute('aria-hidden',String(hide));}
 function tick(now){const dt=last?Math.min(50,now-last):16;last=now;const target=scrollY;visual=paused||reduced.matches?target:visual+(target-visual)*(1-Math.exp(-dt/45));if(Math.abs(visual-target)<.15)visual=target;render(visual);if(visual!==target)raf=requestAnimationFrame(tick);else{raf=0;last=0;}}
 function schedule(){if(!raf)raf=requestAnimationFrame(tick);}
 function pause(value){paused=value;document.body.classList.toggle('paused',value);motion.setAttribute('aria-pressed',String(value));motion.setAttribute('aria-label',value?'Reprendre les animations':'Mettre les animations en pause');motion.textContent=value?'▷':'Ⅱ';render(scrollY);}
 motion.addEventListener('click',()=>pause(!paused));reduced.addEventListener('change',()=>{pause(reduced.matches);measure();});window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',measure);document.fonts.ready.then(measure);document.querySelectorAll('.stage img').forEach(i=>i.addEventListener('load',measure));
 function closeMenu(){header.classList.remove('menu-open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Ouvrir le menu');menu.textContent='☰';}
 menu.addEventListener('click',()=>{const open=header.classList.toggle('menu-open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu');menu.textContent=open?'×':'☰';});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&header.classList.contains('menu-open')){closeMenu();menu.focus();}});document.addEventListener('click',e=>{if(header.classList.contains('menu-open')&&!header.contains(e.target))closeMenu();});
 const targets={'#accueil':()=>start,'#surface':()=>start,'#passage':()=>start+stops[1].x,'#temple':()=>start+stops[2].x};document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',e=>{closeMenu();const hash=a.getAttribute('href');if(targets[hash]){e.preventDefault();history.replaceState(null,'',hash);scrollTo({top:targets[hash](),behavior:reduced.matches?'instant':'smooth'});}}));
 let initial=false;function ready(){measure();if(!initial){initial=true;if(targets[location.hash]){scrollTo({top:targets[location.hash](),behavior:'instant'});visual=scrollY;render(visual);}}}document.fonts.ready.then(ready);window.addEventListener('load',measure);new ResizeObserver(()=>{if(!raf)measure();}).observe(journey);measure();pause(paused);
})();
